<script setup>
import {onBeforeUnmount,onMounted,reactive,ref} from 'vue';
const props=defineProps({mode:String,indexUrl:String,csrf:String,submitUrl:String,payload:String,errors:String,old:String});
function parse(v){try{return JSON.parse(v||'{}')}catch{return {}}}const payload=parse(props.payload),errors=parse(props.errors),old=parse(props.old),message=payload.message||{};
const state=reactive({rows:[],pagination:{},stats:{},filters:{search:new URLSearchParams(location.search).get('search')||'',status:new URLSearchParams(location.search).get('status')||''},loading:false,error:'',reply:{subject:old.subject??('Re: '+(message.subject||'')),body:old.reply??''}});
let abort;
async function load(url=props.indexUrl,push=false){abort?.abort();abort=new AbortController();state.loading=true;state.error='';try{const r=await fetch(url,{credentials:'same-origin',signal:abort.signal,headers:{Accept:'application/json','X-Requested-With':'XMLHttpRequest'}}),d=await r.json();if(!r.ok)throw new Error(d.message||'Unable to load messages');state.rows=d.messages||[];state.pagination=d.pagination||{};state.stats=d.stats||{};state.filters={search:'',status:'',...(d.filters||{})};if(push)history.pushState({},'',url)}catch(e){if(e.name!=='AbortError')state.error=e.message}finally{state.loading=false}}
function filter(){const u=new URL(props.indexUrl,location.origin);Object.entries(state.filters).forEach(([k,v])=>v&&u.searchParams.set(k,v));load(u.href,true)}function page(l){l.url&&load(l.url,true)}
async function markUnread(){const form=new FormData();form.append('_method','PATCH');form.append('_token',props.csrf);await fetch(payload.unread_url,{method:'POST',credentials:'same-origin',headers:{'X-CSRF-TOKEN':props.csrf,'X-Requested-With':'XMLHttpRequest'},body:form});location.href=props.indexUrl}
async function remove(url,title='message'){let ok=confirm('Delete '+title+'?');if(window.Swal){const r=await window.Swal.fire({title:'Delete message?',text:title,icon:'warning',showCancelButton:true,confirmButtonText:'Delete'});ok=r.isConfirmed}if(!ok)return;const f=new FormData();f.append('_method','DELETE');const r=await fetch(url,{method:'POST',credentials:'same-origin',headers:{'X-CSRF-TOKEN':props.csrf,'X-Requested-With':'XMLHttpRequest','Accept':'application/json'},body:f});if(r.ok)location.href=props.indexUrl;else state.error='Message could not be deleted.'}
async function markRowUnread(row){const body=new FormData();body.append('_method','PATCH');body.append('_token',props.csrf);await fetch(row.unread_url,{method:'POST',credentials:'same-origin',headers:{'X-CSRF-TOKEN':props.csrf,'X-Requested-With':'XMLHttpRequest'},body});await load(location.href)}
function pop(){load(location.href)}
onMounted(()=>{if(props.mode==='index')load(props.indexUrl+location.search);window.addEventListener('popstate',pop)});onBeforeUnmount(()=>{abort?.abort();window.removeEventListener('popstate',pop)});
</script>
<template>
<div v-if="mode==='index'" class="messages-page">
<div class="page-header mb-4"><h1 class="page-title">Messages</h1><p class="page-subtitle">Review and respond to customer messages.</p></div>
<div class="row g-4 mb-4"><div v-for="item in [{k:'total',l:'Total Messages',i:'chat-left-text'},{k:'unread',l:'Unread',i:'envelope'},{k:'read',l:'Read',i:'envelope-open'},{k:'today',l:'Today',i:'calendar-day'}]" :key="item.k" class="col-12 col-sm-6 col-xl-3"><div class="message-stat-card"><div class="message-stat-icon"><i class="bi" :class="'bi-'+item.i"></i></div><span class="message-stat-label">{{item.l}}</span><strong>{{state.stats[item.k]||0}}</strong></div></div></div>
<div class="message-card mb-4"><div class="message-card-header"><h5>Search messages</h5></div><form class="p-3" @submit.prevent="filter"><div class="row g-3 align-items-end"><div class="col-12 col-lg-7"><label class="form-label">Search</label><div class="message-search-group"><i class="bi bi-search"></i><input v-model="state.filters.search" class="form-control" placeholder="Name, email, subject or message"></div></div><div class="col-12 col-lg-3"><label class="form-label">Status</label><select v-model="state.filters.status" name="status" class="form-select"><option value="">All statuses</option><option value="unread">Unread</option><option value="read">Read</option></select></div><div class="col-12 col-lg-2 d-flex gap-2"><button class="btn message-search-btn"><i class="bi bi-search"></i> Filter</button><button type="button" class="btn message-reset-btn w-100" @click="state.filters={search:'',status:''};filter()"><i class="bi bi-arrow-counterclockwise"></i></button></div></div></form></div>
<div v-if="state.error" class="alert alert-danger">{{state.error}} <button class="btn btn-sm btn-light" @click="load()">Retry</button></div><div class="message-card"><div class="message-card-header"><h5>Inbox</h5></div><div class="table-responsive"><table class="table message-table align-middle mb-0"><thead><tr><th>ID</th><th>Sender</th><th>Subject</th><th>Status</th><th>Date</th><th class="text-end">Actions</th></tr></thead><tbody><tr v-if="state.loading"><td colspan="6" class="text-center py-4">Loading messages…</td></tr><tr v-for="row in state.rows" v-else :key="row.id" :class="row.status==='unread'?'message-unread':''"><td><span class="message-id">#{{row.id}}</span></td><td><div class="message-sender"><div class="message-avatar">{{row.name.slice(0,1).toUpperCase()}}</div><div class="message-sender-info"><strong>{{row.name}}</strong><small>{{row.email}}</small></div></div></td><td><div class="message-subject">{{row.subject}}</div><div class="message-preview">{{row.preview}}</div></td><td><span class="message-status" :class="row.status"><i class="bi" :class="row.status==='unread'?'bi-envelope':'bi-envelope-open'"></i>{{row.status}}</span></td><td><div class="message-date">{{row.date}}<small class="d-block">{{row.time}}</small></div></td><td><div class="message-actions justify-content-end"><a :href="row.show_url" class="message-action-btn view" title="View"><i class="bi bi-eye"></i></a><button v-if="row.status==='read'" class="message-action-btn unread-btn" title="Mark unread" @click="markRowUnread(row)"><i class="bi bi-envelope"></i></button><button class="message-action-btn delete" title="Delete" @click="remove(row.delete_url,row.subject)"><i class="bi bi-trash"></i></button></div></td></tr><tr v-if="!state.loading&&!state.rows.length"><td colspan="6"><div class="message-empty"><div class="message-empty-icon"><i class="bi bi-chat-left-text"></i></div><p>No messages found.</p></div></td></tr></tbody></table></div><div v-if="state.pagination.total>10" class="message-pagination"><span class="message-pagination-info">Showing {{state.pagination.first_item}}–{{state.pagination.last_item}} of {{state.pagination.total}}</span><div class="message-pagination-links"><button v-for="(l,i) in state.pagination.links" :key="i" class="page-link" :disabled="!l.url" :class="{active:l.active}" @click="page(l)" v-html="l.label"></button></div></div></div></div>
<div v-else-if="mode==='reply'||mode==='site-reply'" class="messages-page"><header class="messages-header mb-4"><div><h1 class="messages-title">{{mode==='reply'?'Reply to Message':'Reply in Site'}}</h1><p class="messages-subtitle">Respond to {{message.name}} through {{mode==='reply'?'email':'SecondBook'}}.</p></div><a :href="message.show_url||payload.show_url" class="btn messages-back-btn"><i class="bi bi-arrow-left"></i> Back to message</a></header><div v-if="Object.keys(errors).length" class="alert alert-danger"><ul class="mb-0"><li v-for="(e,k) in errors" :key="k">{{e[0]}}</li></ul></div><div class="message-detail-card"><div class="message-detail-top"><div class="message-detail-user"><div class="message-avatar">{{message.name?.slice(0,1).toUpperCase()}}</div><div><strong>{{message.name}}</strong><div>{{message.email}}</div></div></div></div><div class="message-detail-section"><span class="message-detail-label">Original message</span><h2 class="message-detail-subject">{{message.subject}}</h2><div class="message-detail-body">{{message.body}}</div></div><form :action="submitUrl" method="POST" class="p-4"><input type="hidden" name="_token" :value="csrf"><div v-if="mode==='reply'" class="message-detail-section"><label class="message-detail-label" for="subject">Subject</label><input id="subject" v-model="state.reply.subject" name="subject" class="form-control" maxlength="255" required><small v-if="errors.subject" class="text-danger">{{errors.subject[0]}}</small></div><div class="message-detail-section"><label class="message-detail-label" for="reply">Reply</label><textarea id="reply" v-model="state.reply.body" name="reply" rows="8" class="form-control" maxlength="10000" required></textarea><small v-if="errors.reply" class="text-danger">{{errors.reply[0]}}</small></div><div class="message-detail-actions"><a :href="payload.show_url" class="btn btn-light">Cancel</a><button type="submit" class="btn btn-primary"><i class="bi bi-send"></i> Send reply</button></div></form></div></div>
<div v-else class="messages-page"><header class="messages-header mb-4"><div><h1 class="messages-title">Message Details</h1><p class="messages-subtitle">Review the customer message and choose a response.</p></div><a :href="indexUrl" class="btn messages-back-btn"><i class="bi bi-arrow-left"></i> Back to messages</a></header><div class="message-detail-card"><div class="message-detail-top"><div class="message-detail-user"><div class="message-avatar">{{message.name?.slice(0,1).toUpperCase()}}</div><div><strong>{{message.name}}</strong><div>{{message.email}}</div></div></div><div class="message-detail-status"><span class="message-status" :class="message.status"><i class="bi" :class="message.status==='unread'?'bi-envelope':'bi-envelope-open'"></i>{{message.status}}</span></div></div><div class="message-detail-divider"></div><div class="message-detail-section"><span class="message-detail-label">Subject</span><h3 class="message-detail-subject">{{message.subject}}</h3><div class="message-detail-meta"><span>{{message.created_at}}</span></div></div><div class="message-detail-section"><span class="message-detail-label">Message</span><div class="message-detail-body">{{message.body}}</div></div><div class="message-detail-actions"><form v-if="message.status==='read'" @submit.prevent="markUnread"><button class="btn btn-outline-secondary mark-unread-btn"><i class="bi bi-envelope"></i> Mark unread</button></form><a :href="payload.reply_url" class="btn btn-primary"><i class="bi bi-envelope"></i> Reply by email</a><a v-if="payload.site_reply_url" :href="payload.site_reply_url" class="btn btn-outline-primary"><i class="bi bi-chat-left-text"></i> Reply in site</a><button class="btn btn-outline-danger" @click="remove(payload.delete_url,message.subject)"><i class="bi bi-trash"></i></button></div></div></div>
</template>
